import 'package:cephalopod/core/board/models/player_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'headline_ui.freezed.dart';

/// What the line above the board is about: whose turn it is, or who won and
/// by how much. One case per situation, so each maps to exactly one message,
/// which `HeadlineTextMapper` words.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
sealed class HeadlineUi with _$HeadlineUi {
  /// Between two people, [player] is to move.
  const factory HeadlineUi.playerToMove(PlayerUi player) = PlayerToMoveHeadline;

  /// Against the computer, the person is to move.
  const factory HeadlineUi.personToMove() = PersonToMoveHeadline;

  /// Against the computer, the computer is to move, so it is choosing its
  /// move.
  const factory HeadlineUi.computerToMove() = ComputerToMoveHeadline;

  /// A hint is being looked for, for whoever is to move.
  const factory HeadlineUi.lookingForHint() = LookingForHintHeadline;

  /// Between two people, [player] won with [winnerDice] to [loserDice].
  const factory HeadlineUi.playerWon({
    required PlayerUi player,
    required int winnerDice,
    required int loserDice,
  }) = PlayerWonHeadline;

  /// The person beat the computer, with [winnerDice] to [loserDice].
  const factory HeadlineUi.personWon({
    required int winnerDice,
    required int loserDice,
  }) = PersonWonHeadline;

  /// The computer won, with [winnerDice] to [loserDice].
  const factory HeadlineUi.computerWon({
    required int winnerDice,
    required int loserDice,
  }) = ComputerWonHeadline;
}
